fixed = imread('cameraman.tif');
moving = imrotate(fixed, 7, 'bilinear', 'crop');
[optimizer, metric] = imregconfig('monomodal');
reg = imregister(moving, fixed, 'rigid', optimizer, metric);
imshowpair(fixed, reg, 'falsecolor')

[optimizer, metric] = imregconfig('multimodal');
optimizer.InitialRadius = 6.25e-3;
tform = imregtform(moving, fixed, 'affine', optimizer, metric);
disp(tform.A)
reg = imwarp(moving, tform, 'OutputView', imref2d(size(fixed)));

[opt, met] = imregconfig('multimodal');
opt.InitialRadius = 0.009;
opt.Epsilon = 1.5e-4;
opt.GrowthFactor = 1.01;
opt.MaximumIterations = 300;
tform = imregtform(moving, fixed, 'rigid', opt, met);

